import {startI18n,currentLocale,localize} from './i18n.mjs';
await startI18n();
import {normalize,extractNumbers,matchCards} from './matcher.mjs';
const $=s=>document.querySelector(s),fmt=n=>Number(n).toLocaleString(currentLocale()),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let workerLanguage='';let cards=[],sets={},view='all',limit=24,language='en',catalogTicket=0,detailTicket=0,ready=false,saved=[],worker=null,workerPromise=null,photo=null,busy=false,photoUrl=null;
try{let v=JSON.parse(localStorage.getItem('kaartkompas-saved-v2')||'[]');if(Array.isArray(v))saved=v}catch{}
const toast=t=>{ $('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)};
async function getJSON(url){const r=await fetch(url,{signal:AbortSignal.timeout(30000),credentials:"omit",referrerPolicy:"no-referrer"});if(!r.ok)throw Error('Bron niet beschikbaar ('+r.status+')');return r.json()}
function persist(){try{localStorage.setItem('kaartkompas-saved-v2',JSON.stringify(saved))}catch{toast('Bewaren op dit toestel lukt niet. Exporteer je kaarten als back-up.')}$('#savedCount').textContent=saved.length}
const key=c=>(c.lang||language)+':'+c.id;
function isSaved(c){return saved.some(x=>key(x)===key(c))}
function toggleSaved(c){if(isSaved(c))saved=saved.filter(x=>key(x)!==key(c));else saved.push({...c,lang:c.lang||language,setName:c.setName||sets[c.setId]?.name});persist();render()}
function image(c,high=false){return c.image?c.image+'/'+(high?'high':'low')+'.webp':''}
function pic(c,high=false){return c.image?'<img '+(!high?'loading="lazy" ':'')+'src="'+escape(image(c,high))+'" alt="'+escape(c.name)+'">':'<div class="placeholder">◈<br>Afbeelding nog niet beschikbaar</div>'}
function protectImage(root){root.querySelectorAll('img').forEach(i=>i.addEventListener('error',()=>{const p=document.createElement('div');p.className='placeholder';p.textContent='Afbeelding niet beschikbaar';i.replaceWith(p)},{once:true}))}
function cardElement(c){const el=document.createElement('article');el.className='card';el.innerHTML='<button class="heart '+(isSaved(c)?'saved':'')+'" aria-label="'+(isSaved(c)?'Verwijder':'Bewaar')+' '+escape(c.name)+'">'+(isSaved(c)?'♥':'♡')+'</button><button class="art" aria-label="Bekijk '+escape(c.name)+'">'+pic(c)+'</button><div class="info"><h3>'+escape(c.name)+'</h3><div class="meta"><span>'+escape(c.setName||sets[c.setId]?.name||c.setId)+'</span><span>#'+escape(c.localId)+'</span></div><span class="tag">'+escape((c.lang||language).toUpperCase())+' · '+escape(c.id)+'</span></div>';el.querySelector('.heart').onclick=()=>toggleSaved(c);el.querySelector('.art').onclick=()=>show(c);protectImage(el);return el}
function nav(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#collectionTools').hidden=view!=='saved'}
function filtered(){let q=$('#query').value.trim(),n=normalize(q),nums=extractNumbers(q);let result=view==='saved'?saved:cards;return result.filter(c=>{if($('#setFilter').value&&c.setId!==$('#setFilter').value)return false;if($('#imagesOnly').checked&&!c.image)return false;if(!q)return true;if(nums.length){let p=nums[0];return c.localId.replace(/^0+/,'').toLowerCase()===p.localId.replace(/^0+/,'').toLowerCase()&&Number(sets[c.setId]?.cardCount?.official)===Number(p.total)}if(/^\d+$/.test(q))return Number(c.localId)===Number(q);return normalize(c.name).includes(n)||normalize(c.id)===n})}
function render(){nav();$('#grid').replaceChildren();$('#shownCount').textContent='';$('#more').hidden=true;if(view==='sets'){renderSets();return}$('#grid').className='grid';let result=filtered();let sort=$('#sort').value;if(sort==='az'||sort==='za')result.sort((a,b)=>(sort==='za'?-1:1)*a.name.localeCompare(b.name));if(sort==='num')result.sort((a,b)=>a.localId.localeCompare(b.localId,undefined,{numeric:true}));$('#heading').textContent=view==='saved'?'Mijn bewaarde kaarten':$('#query').value?'Zoekresultaten':$('#setFilter').value?sets[$('#setFilter').value]?.name||'Kaarten':'Ontdek kaarten';$('#status').textContent=fmt(result.length)+' kaarten'+(view==='saved'?' · op dit toestel':' · '+$('#language').selectedOptions[0].textContent);if(!ready&&view!=='saved'){$('#grid').innerHTML='<div class="empty">Catalogus laden…</div>';return}if(!result.length){$('#grid').innerHTML='<div class="empty">'+(view==='saved'?'Je hebt hier nog geen passende kaarten bewaard.<br>Gebruik het hartje bij een kaart.':'Geen kaarten gevonden. Probeer een andere naam of wis de filters.')+'</div>';return}const frag=document.createDocumentFragment();result.slice(0,limit).forEach(c=>frag.append(cardElement(c)));$('#grid').append(frag);$('#more').hidden=result.length<=limit;$('#shownCount').textContent=fmt(Math.min(limit,result.length))+' van '+fmt(result.length)}
function renderSets(){let q=normalize($('#query').value);let list=Object.values(sets).filter(s=>!q||normalize(s.name+' '+s.id).includes(q));$('#grid').className='sets';$('#heading').textContent='Sets & series';$('#status').textContent=fmt(list.length)+' sets · '+$('#language').selectedOptions[0].textContent;list.slice(0,limit).forEach(s=>{const b=document.createElement('button');b.className='set';b.innerHTML=(s.logo?'<img loading="lazy" src="'+escape(s.logo)+'.webp" alt="">':'')+'<strong>'+escape(s.name)+'</strong><span>'+fmt(s.cardCount?.total||0)+' kaarten · '+escape(s.id)+' →</span>';b.onclick=()=>{view='all';$('#query').value='';$('#setFilter').value=s.id;limit=24;render()};protectImage(b);$('#grid').append(b)});if(!list.length)$('#grid').innerHTML='<div class="empty">Geen sets gevonden.</div>';$('#more').hidden=list.length<=limit;$('#shownCount').textContent=fmt(Math.min(limit,list.length))+' van '+fmt(list.length)}
async function loadCatalog(lang){const ticket=++catalogTicket;ready=false;language=lang;cards=[];sets={};$('#catalogStatus').textContent='Kaartencatalogus laden…';render();try{const [cs,ss,meta]=await Promise.all(lang==='en'?[getJSON('./data/cards-en.json'),getJSON('./data/sets-en.json'),getJSON('./data/meta.json')]:[getJSON('https://api.tcgdex.net/v2/'+lang+'/cards'),getJSON('https://api.tcgdex.net/v2/'+lang+'/sets')]);if(ticket!==catalogTicket)return;if(!Array.isArray(cs)||!Array.isArray(ss))throw Error('Onverwachte brongegevens');sets=Object.fromEntries(ss.map(s=>[s.id,s]));cards=cs.map(c=>({...c,setId:c.setId||c.id.slice(0,c.id.lastIndexOf('-')),lang}));$('#setFilter').replaceChildren(new Option('Alle sets',''),...ss.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(s=>new Option(s.name,s.id)));ready=true;if(lang==='en')$('#indexDate').textContent=new Date(meta.updated).toLocaleDateString(currentLocale());$('#catalogStatus').textContent=fmt(cards.length)+' kaartvermeldingen · '+fmt(ss.length)+' sets · '+(lang==='en'?'Eigen index van TCGdex, bijgewerkt '+new Date(meta.updated).toLocaleDateString(currentLocale()):'Live catalogus van TCGdex')+' · Beschikbaarheid verschilt per taal.';limit=24;render()}catch(e){if(ticket!==catalogTicket)return;$('#catalogStatus').replaceChildren(document.createTextNode('Catalogus laden lukt niet. Controleer je verbinding. '));let retry=document.createElement('button');retry.className='outline';retry.textContent='Opnieuw proberen';retry.onclick=()=>loadCatalog(lang);$('#catalogStatus').append(retry);$('#grid').innerHTML='<div class="empty">De catalogus is nu niet beschikbaar. Je bewaarde kaarten blijven bereikbaar.</div>'}}
function detailRow(label,value){return value!==undefined&&value!==null&&value!==''?'<tr><th>'+escape(label)+'</th><td>'+escape(value)+'</td></tr>':''}
async function show(c){const ticket=++detailTicket;const lang=c.lang||language;const modal=$('#modal');$('#detail').innerHTML='<div class="api-spinner">Kaartinformatie ophalen…</div>';if(!modal.open)modal.showModal();try{const d=await getJSON('https://api.tcgdex.net/v2/'+lang+'/cards/'+encodeURIComponent(c.id));if(ticket!==detailTicket)return;const total=d.set?.cardCount?.official;const converted={...c,image:d.image||c.image,setId:d.set?.id||c.setId,setName:d.set?.name||c.setName,lang};let rows=detailRow('Set',d.set?.name)+detailRow('Kaartnummer',d.localId+(total?'/'+total:''))+detailRow('Categorie',d.category)+detailRow('HP',d.hp)+detailRow('Type',d.types?.join(', '))+detailRow('Zeldzaamheid',d.rarity)+detailRow('Evolutiefase',d.stage)+detailRow('Evolueert van',d.evolveFrom)+detailRow('Illustrator',d.illustrator)+detailRow('Kaart-ID',d.id);let attacks=(d.attacks||[]).map(a=>'<div class="attack"><strong>'+escape(a.name)+' '+escape(a.damage||'')+'</strong><p>'+escape(a.effect||'')+'</p><small>'+escape(a.cost?.join(' · ')||'')+'</small></div>').join('');let abilities=(d.abilities||[]).map(a=>'<div class="attack"><strong>'+escape(a.name)+'</strong><p>'+escape(a.effect)+'</p></div>').join('');let search=encodeURIComponent(d.name+' '+d.localId+' '+(d.set?.name||''));let marketplace='<a href="https://www.cardmarket.com/en/Pokemon/Products/Search?searchString='+search+'" target="_blank" rel="noopener noreferrer">Cardmarket ↗</a><a href="https://www.tcgplayer.com/search/pokemon/product?productLineName=pokemon&q='+search+'&view=grid" target="_blank" rel="noopener noreferrer">TCGplayer ↗</a><a href="https://www.ebay.nl/sch/i.html?_nkw='+search+'" target="_blank" rel="noopener noreferrer">eBay ↗</a><a href="https://www.pokemonkaart.nl/zoeken" target="_blank" rel="noopener noreferrer">Pokemonkaart.nl — zoekpagina ↗</a>';$('#detail').innerHTML='<div class="detail">'+pic(converted,true)+'<div class="detail-content"><div class="eyebrow">'+escape(lang.toUpperCase())+' · '+escape(d.set?.name)+'</div><h1 style="font-size:30px">'+escape(d.name)+'</h1><button id="detailSave" class="outline">'+(isSaved(converted)?'♥ Verwijder uit bewaard':'♡ Bewaar deze kaart')+'</button><table>'+rows+'</table>'+(d.description?'<p>'+escape(d.description)+'</p>':'')+abilities+attacks+'<h3>Bekijk prijzen bij de bron</h3><div class="links">'+marketplace+'</div><p class="notice">De links openen zoekresultaten bij de aanbieder. Controleer taal, conditie en drukvariant. Er worden hier geen actuele prijzen weergegeven.</p><button class="textbutton" id="copySearch">Kopieer naam en kaartnummer</button><p class="notice">Kaartinformatie via TCGdex.</p></div></div>';protectImage($('#detail'));$('#detailSave').onclick=()=>{toggleSaved(converted);$('#detailSave').textContent=isSaved(converted)?'♥ Verwijder uit bewaard':'♡ Bewaar deze kaart'};$('#copySearch').onclick=async()=>{try{await navigator.clipboard.writeText(d.name+' '+d.localId+(total?'/'+total:''));toast('Naam en kaartnummer gekopieerd')}catch{toast('Kopiëren lukt niet in deze browser')}}}catch(e){if(ticket!==detailTicket)return;$('#detail').replaceChildren();let title=document.createElement('h2');title.textContent=c.name;let p=document.createElement('p');p.textContent='Uitgebreide kaartinformatie is nu niet bereikbaar. Probeer het opnieuw.';let b=document.createElement('button');b.className='primary';b.textContent='Opnieuw proberen';b.onclick=()=>show(c);$('#detail').append(title,p,b)}}
function doMatch(){if(!ready){$('#matchStatus').textContent='Wacht tot de catalogus is geladen.';return}const text=$('#scanText').value.trim();if(!text){$('#matchStatus').textContent='Kies een foto of vul een naam / kaartnummer in.';return}const hits=matchCards(text,cards,sets,{setId:$('#setFilter').value,limit:16});$('#matches').replaceChildren();$('#matchStatus').textContent=hits.length?'Mogelijke overeenkomsten — controleer zelf de afbeelding, set en het nummer. Dit is geen definitieve identificatie.':'Geen overtuigende overeenkomst. Verbeter de naam of het nummer hierboven, probeer een scherpere foto of kies de juiste kaarttaal.';hits.forEach(({card:c,reasons})=>{let b=document.createElement('button');b.className='match';b.innerHTML=pic(c)+'<strong>'+escape(c.name)+'</strong><small>'+escape(sets[c.setId]?.name||c.setId)+' · #'+escape(c.localId)+'</small><small>'+escape(reasons.join(' · '))+'</small>';b.onclick=()=>show(c);protectImage(b);$('#matches').append(b)})}
async function loadOCR(){if(window.Tesseract)return;if(!workerPromise)workerPromise=new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Tekstherkenning kon niet worden geladen'));document.head.append(s)});try{await workerPromise}catch(e){workerPromise=null;throw e}}
async function recognize(){if(!photo||busy)return;busy=true;$('#recognizeAgain').disabled=true;$('#cameraButton').disabled=true;$('#uploadButton').disabled=true;$('#scanProgress').hidden=false;$('#scanProgress').value=0;$('#scanStatus').textContent='Tekstherkenning laden. De eerste keer kan dit wat langer duren…';try{await loadOCR();const ocrLanguage=({en:'eng',fr:'fra',de:'deu',es:'spa',it:'ita',pt:'por',ja:'jpn'})[language]||'eng';if(worker&&workerLanguage!==ocrLanguage){await worker.terminate();worker=null}if(!worker){workerLanguage=ocrLanguage;worker=await Tesseract.createWorker(ocrLanguage,1,{cacheMethod:'none',workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0',langPath:'https://tessdata.projectnaptha.com/4.0.0',logger:m=>{if(m.status==='recognizing text'){$('#scanProgress').value=m.progress;$('#scanStatus').textContent='Tekst herkennen… '+Math.round(m.progress*100)+'%'}}})};const bitmap=await createImageBitmap(photo);const canvas=document.createElement('canvas');const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let result=await worker.recognize(canvas);$('#scanText').value=result.data.text.trim();$('#scanProgress').value=1;$('#scanStatus').textContent='Tekst gelezen. Controleer de naam en het kaartnummer hieronder.';doMatch()}catch(e){$('#scanStatus').textContent='Automatisch lezen is niet gelukt. Probeer een JPG/PNG-foto, een scherpere opname of voer de naam en het nummer handmatig in.';if(worker){try{await worker.terminate()}catch{}worker=null}}finally{busy=false;$('#scanProgress').hidden=true;$('#recognizeAgain').disabled=false;$('#cameraButton').disabled=false;$('#uploadButton').disabled=false}}
async function choosePhoto(file){if(!file||busy)return;if(file.size>30*1024*1024){toast('Gebruik een foto kleiner dan 30 MB.');return}photo=file;if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(file);$('#scanPreview').src=photoUrl;$('#scanPreview').hidden=false;$('#photoPlaceholder').hidden=true;$('#recognizeAgain').hidden=false;$('#matches').replaceChildren();$('#matchStatus').textContent='';await recognize()}
$('#openScan').onclick=()=>{$('#scanPanel').hidden=false;$('#scanPanel').scrollIntoView({behavior:'smooth',block:'start'})};$('#closeScan').onclick=()=>$('#scanPanel').hidden=true;$('#cameraButton').onclick=()=>$('#cameraInput').click();$('#uploadButton').onclick=()=>$('#uploadInput').click();for(const id of ['cameraInput','uploadInput'])$('#'+id).onchange=e=>{choosePhoto(e.target.files[0]);e.target.value=''};$('#recognizeAgain').onclick=recognize;$('#matchButton').onclick=doMatch;
$('#language').onchange=()=>{ $('#matches').replaceChildren();$('#matchStatus').textContent='';loadCatalog($('#language').value)};$('#setFilter').onchange=()=>{limit=24;render()};$('#imagesOnly').onchange=render;$('#sort').onchange=render;$('#search').onsubmit=e=>{e.preventDefault();limit=24;render()};let debounce;$('#query').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{limit=24;render()},180)};document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.q;view='all';limit=24;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;limit=24;render()});$('#reset').onclick=()=>{$('#query').value='';$('#setFilter').value='';$('#imagesOnly').checked=false;limit=24;render()};$('#more').onclick=()=>{limit+=24;render()};$('.close').onclick=()=>{$('#modal').close();detailTicket++};$('#modal').onclick=e=>{if(e.target===$('#modal')){$('#modal').close();detailTicket++}};$('#modal').addEventListener('cancel',()=>detailTicket++);
$('#exportSaved').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),cards:saved},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bindtopia-verzameling.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};$('#importSaved').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10e6)throw Error();const data=JSON.parse(await f.text());if(data.version!==2||!Array.isArray(data.cards))throw Error();const valid=data.cards.filter(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.localId==='string'&&typeof c.setId==='string'&&/^[a-z]{2}$/.test(c.lang)&&(!c.image||/^https:\/\/assets\.tcgdex\.net\//.test(c.image)));if(valid.length!==data.cards.length)throw Error();const merged=new Map(saved.map(c=>[key(c),c]));valid.forEach(c=>merged.set(key(c),c));saved=[...merged.values()];persist();render();toast('Back-up geïmporteerd')}catch{toast('Dit bestand is geen geldige Bindtopia-back-up.')}finally{e.target.value=''}};
$('#savedCount').textContent=saved.length;loadCatalog('en');

function clearScan(){if(busy){toast('Wacht tot de tekstherkenning klaar is en wis dan de scan.');return false}photo=null;if(photoUrl){URL.revokeObjectURL(photoUrl);photoUrl=null}$('#scanPreview').removeAttribute('src');$('#scanPreview').hidden=true;$('#photoPlaceholder').hidden=false;$('#scanText').value='';$('#matches').replaceChildren();$('#matchStatus').textContent='';$('#scanStatus').textContent='De scan is gewist. Kies een nieuwe foto om te beginnen.';$('#recognizeAgain').hidden=true;return true}
$('#clearScan').onclick=clearScan;
$('#closeScan').onclick=()=>{if(clearScan())$('#scanPanel').hidden=true};
$('#clearSaved').onclick=()=>{if(!confirm(localize('Alle bewaarde kaarten uit deze browser verwijderen? Exporteer eerst een back-up als je ze wilt behouden.')))return;try{localStorage.removeItem('kaartkompas-saved-v2');localStorage.removeItem('kaartkompas-saved')}catch{toast('Wissen is niet gelukt. Verwijder de sitegegevens via je browser.');return}saved=[];$('#savedCount').textContent='0';render();toast('Bewaarde kaarten uit deze browser verwijderd.')};

getJSON('./project.json').then(config=>{if(/^[a-z0-9-]+$/i.test(config.sponsorsUsername)){const link=$('#sponsorLink');link.href='https://github.com/sponsors/'+config.sponsorsUsername;link.hidden=false}}).catch(()=>{});

document.addEventListener('interface-language-change',()=>{render()});
